  "Давхаргын хуучирсан `GUITS_HV` талбар 2026-08-24-нд эх өгөгдлөөс гарсан тул зөвхөн энэ нэг тоо бий.": "The layer's deprecated `GUITS_HV` field was removed from the source data on 2026-08-24, so only this single figure remains.",
  "⚠️ Энэ давхаргад гүйцэтгэлийн ХУВЬ БАЙХГҮЙ — зөвхөн геометр ба таних тэмдэг ": "⚠️ This layer carries NO progress percentage — only geometry and identity ",
  "(багц · блок · гүйцэтгэгч · давхар · айл · төрөл). Гүйцэтгэл асуувал `compute` ": "(package · block · contractor · floors · households · type). For progress use the `compute` ",
  "хэрэгслийг ашигла — тэр нь «Гүйцэтгэл бөглөх» хүснэгтээс блок бүрээр тооцдог. ": "tool — it derives it per block from the “Гүйцэтгэл бөглөх” sheet. ",
