  "Ажлын нэр. Бүлгийн мөрд ХООСОН — нэр нь № дотор байдаг": "Task name. EMPTY on group rows — the name lives inside the No. column",
  "Хувийн жин 0–1. Шатлал ялгахад ч хэрэглэгддэг (толгой = 1)": "Relative weight 0–1. Also used to tell hierarchy levels apart (headers = 1)",
