  "Энэ илгээлт аль хэдийн шийдвэрлэгдсэн байна. Хуудсаа шинэчилнэ үү.": "This submission has already been decided. Please refresh the page.",
  "Танд батлах хуваарь алга — гүйцэтгэгч илгээмэгц энд гарч ирнэ. Хуваарийг та зөвхөн харна, засахгүй.": "You have no schedule to approve — one appears here as soon as a contractor submits it. You can view the schedule but not edit it.",
