  "Ажлын шатлал татагдсангүй тул хүснэгт хавтгай харагдаж байна — бүлгийн шүүлт ба эвхэлт ажиллахгүй. Бөглөлт хэвийн хэвээр.": "The work hierarchy could not be loaded, so the table is flat — group filtering and collapsing are unavailable. Filling in still works normally.",
  "Бүх ажилд баримт бөглөгдсөн байна. Бүгдийг харах бол «Зөвхөн бөглөөгүй»-г унтраа.": "Every work row has a document filled in. Turn off “Only unfilled” to see them all.",
