  "Хяналтын үйлчилгээний талбаруудыг шалгаж чадсангүй — баталгаажуулалт хадгалагдах эсэх тодорхойгүй тул түр хаалттай.": "The review service fields could not be checked — it is unclear whether an approval would be saved, so this is disabled for now.",
  "«{0}»: архивт бичих жааз {1} мөр боловч лавлах {2} мөр байна — зөрүүтэй жааз бичвэл энэ багцын хуудас дараагийн ачаалалтад бүрмөсөн хаагдана. Архивт ЮУ Ч бичсэнгүй.": "\"{0}\": the snapshot to be written to the archive has {1} rows, but the reference is {2} — writing a mismatched snapshot would lock this package’s sheet out permanently on the next load. NOTHING was written to the archive.",
  "«{0}»: угсарсан жааз {1} мөр — ачаалсан {2} мөрөөс БОГИНО. Архивт ЮУ Ч бичсэнгүй.": "\"{0}\": the assembled snapshot has {1} rows — SHORTER than the {2} rows that were loaded. NOTHING was written to the archive.",
  "Бөглөх хуудасны «Б.» мөрийн гүйцэтгэл хэмжигдээгүй тул нэгтгэлд бичсэнгүй — хуудсаа шалгаад дахин баталгаажуулна уу.": "The «Б.» row of the fill sheet has no measured progress, so nothing was written to the summary — check the sheet and approve again.",
