  "Захирамжийн дүнгийн эх үүсвэр — {0}, ₮": "Decree amount source — {0}, ₮",
  "⚠️ САРЫН ХУВААРЬ ЭНД БАЙХГҮЙ. Хуучин `cashflow_0813` (209 мөр) нь гэрээ + сар + өмнөх шилжүүлсэн гэсэн гурван төрлийн мөртэй байсныг 2026-09-06-нд бүрмөсөн хассан. Энэ хүснэгт нь 76 мөр, мөр БҮР НЭГ ГЭРЭЭ — мөрийн төрлөөр шүүх шаардлагагүй. Сар тутмын төлөвлөсөн санхүүжилт, «өмнө шилжүүлсэн», өссөн хувь ОГТ БАЙХГҮЙ; асуувал «бүртгэгддэггүй» гэж хариул. ": "⚠️ THERE IS NO MONTHLY SCHEDULE HERE. The old `cashflow_0813` (209 rows) held three row types — contract + month + previously transferred — and was removed entirely on 2026-09-06. This table has 76 rows, EACH ROW IS ONE CONTRACT — no row-type filter is needed. Monthly planned financing, «previously transferred» and cumulative percentages DO NOT EXIST; if asked, answer that they are not recorded. ",
  "⚠️ Багцаар шүүх/бүлэглэхдээ ЗААВАЛ `{0}` (дэд багц) ашигла; `{1}` нь БАГЦ-16.1…16.7-г нэг болгож нурааж хаяна. ": "⚠️ When filtering/grouping by package ALWAYS use `{0}` (sub-package); `{1}` collapses PACKAGE-16.1…16.7 into one and loses them. ",
  "⚠️ ХУВЬ, ӨССӨН (хуримтлагдсан) дүн, суутгалын томьёо, төлөх дүн, зөрүү — эдгээр багана БАЙХГҮЙ. Хэрэгтэй бол мөрүүдээ татаад ӨӨРӨӨ бод; байхгүй багана нэрлэвэл хүсэлт унана. ": "⚠️ PERCENTAGES, CUMULATIVE amounts, deduction formulas, payable amounts and variances — these columns DO NOT EXIST. Compute them YOURSELF from the rows; naming a missing column makes the request fail. ",
  "⚠️ Огнооны ХОЁР ХЭЛБЭР: `{0}` нь epoch мс, харин `{1}` нь «2024-04-08» гэсэн МӨР. ": "⚠️ TWO DATE FORMATS: `{0}` is epoch ms, while `{1}` is a STRING like «2024-04-08». ",
