  "Буцаах шалтгаанаа бичнэ үү:": "Enter the reason for returning:",
  "Обьём буцаах": "Return volume",
  "Инж. төлөвлөсөн обьём": "Eng. planned volume",
  "Шинээр нэмсэн мөр батлагдаж үндсэн өгөгдөлд орсны ДАРАА нь төлөвлөсөн обьёмыг бичнэ — одоогоор түр дугаартай тул илгээлтэд орохгүй.": "The planned volume can be entered only AFTER the newly added row is approved and written to the source data — it currently has a temporary id, so it cannot be included in a submission.",
  "⚠ Инженерийн төлөвлөсөн обьёмын {0} нүд нь ноорогт хадгалагддаггүй — багц солиход БҮРМӨСӨН устана. Эхлээд «Обьём батлуулах» дарна уу.": "⚠ {0} engineer planned-volume cells are not stored in the draft — switching packages deletes them PERMANENTLY. Press “Submit volume” first.",
  "{0} мөр энэ хуудаснаас олдсонгүй — хуудас хооронд нь шинэчлэгдсэн байна. Хуваарь бичигдсэнгүй; хуудсаа сэргээгээд дахин илгээнэ үү.": "{0} rows were not found on this sheet — it was republished in the meantime. The schedule was NOT written; refresh the page and submit again.",
