  "IPC дугаар (1,2,3…) — ⚠️ ЗӨВХӨН «{0}» мөрд (22/45). «{1}» мөрд ҮРГЭЛЖ хоосон тул «IPC хэд вэ» гэсэн тоонд урьдчилгааг ТООЛОХГҮЙ.": "IPC number (1,2,3…) — ⚠️ ONLY on «{0}» rows (22/45). Always empty on «{1}» rows, so do NOT count advances when answering «how many IPCs».",
  "ТӨЛБӨРИЙН ДҮН, ₮ — ⚠️ БОДИТ ОЛГОСОН дүн (суутгал АЛЬ ХЭДИЙН хасагдсан/байхгүй). 43/45 бөглөгдсөн; хоосон 2 нь «0 ₮ олгосон» БИШ, «бүртгэгдээгүй».": "PAYMENT AMOUNT, ₮ — ⚠️ the ACTUAL DISBURSED amount (deductions ALREADY subtracted / not applicable). 43/45 filled; the 2 empty ones are NOT «0 ₮ disbursed» but «not recorded».",
  "Гүйлгээ хийсэн огноо — DateOnly МӨР «2025-09-25», epoch БИШ. 40/45 (5 хоосон).": "Transaction date — a DateOnly STRING «2025-09-25», NOT epoch. 40/45 (5 empty).",
  "Он — ⚠️ талбарын нэр ДООД ЗУРААСТАЙ (`on_`); `on` гэж бичвэл хүсэлт УНАНА. Integer 2025/2026, огноо БИШ. 43/45.": "Year — ⚠️ the field name has a TRAILING UNDERSCORE (`on_`); writing `on` will make the query FAIL. Integer 2025/2026, NOT a date. 43/45.",
  "Гэрээний код («Багц-1») — ⚠️ ГОЛ БҮЛЭГЛЭХ ТҮЛХҮҮР. 22 гэрээ, 45 мөр. Гэрээний түвшний ямар ч тоог ЭНЭ талбараар бүлэглэж MAX/MIN аваад дараа нь нийлүүл. 1 мөрд хоосон.": "Contract code («Багц-1») — ⚠️ THE MAIN GROUPING KEY. 22 contracts, 45 rows. Any contract-level number must be grouped BY THIS FIELD taking MAX/MIN first, and only then summed. Empty on 1 row.",
  "Багц = төсөл арга хэмжээний нэр («Багц-3.1»). Багцаар шүүх/бүлэглэхэд ЭНИЙГ ашигла. ⚠️ «Багц-1-4», «БАГЦ-10,  БАГЦ-11, БАГЦ-13, БАГЦ-15» гэсэн МУЖИЙН утга 2 мөрд бий (нийт 5,971,417,432 ₮) — тэднийг нэг багцад оноож БОЛОХГҮЙ.": "Package = the name of the project measure («Багц-3.1»). Use THIS to filter/group by package. ⚠️ RANGE values «Багц-1-4» and «БАГЦ-10,  БАГЦ-11, БАГЦ-13, БАГЦ-15» occur on 2 rows (5,971,417,432 ₮ in total) — they must NOT be assigned to a single package.",
