  "Төсвийн эх үүсвэр — нийслэлийн төсөв, ₮ (⚠️ зөвхөн 1/45 бөглөгдсөн; бусад нь хэмжигдээгүй, 0 БИШ)": "Budget source — city budget, ₮ (⚠️ only 1/45 filled; the rest are unmeasured, NOT 0)",
  "Төсвийн эх үүсвэр — борлуулалт, ₮ (⚠️ гэрээний түвшний, давтагдана)": "Budget source — sales, ₮ (⚠️ contract-level, repeats)",
  "Гэрээний эх үүсвэр — үнэт цаас, ₮ (⚠️ гэрээний түвшний, давтагдана)": "Contract source — securities, ₮ (⚠️ contract-level, repeats)",
  "Гэрээний эх үүсвэр — нийслэлийн төсөв, ₮ (⚠️ гэрээний түвшний, давтагдана)": "Contract source — city budget, ₮ (⚠️ contract-level, repeats)",
  "Гэрээний эх үүсвэр — борлуулалт, ₮ (⚠️ гэрээний түвшний, давтагдана)": "Contract source — sales, ₮ (⚠️ contract-level, repeats)",
  "Хүлээгдэж буй гүйцэтгэл — ⚠️ 45/45 мөрд МЭДЭЭЛЭЛГҮЙ (null эсвэл 0). Уншихгүй.": "Pending performance — ⚠️ NO DATA on 45/45 rows (null or 0). Do not read it.",
  "⚠️ ГРЕЙН — ХАМГИЙН ЧУХАЛ: мөр = НЭГ ТӨЛБӨРИЙН ГҮЙЛГЭЭ. 45 мөр = 22 гэрээ, ГЭРЭЭНИЙ талбарууд ({0}, {1}, төсвийн/гэрээний эх үүсвэрүүд, гүйцэтгэгч, захирамж) `{2}` бүрд ДАВТАГДАНА. Тэдгээрийг ШУУД SUM() хийвэл Багц-4.1 (7 мөр) нь 7 ДАХИН тоологдоно — ЭХЛЭЭД `{2}`-оор бүлэглэж MAX ав. Төлбөрийн талбарууд ({3}, {4}) харин мөр бүрд өөр тул шууд SUM зөв. ": "⚠️ GRAIN — MOST IMPORTANT: one row = ONE PAYMENT TRANSACTION. 45 rows = 22 contracts, and the CONTRACT fields ({0}, {1}, the budget/contract sources, contractor, decrees) REPEAT for every `{2}`. SUM()-ing them DIRECTLY counts Багц-4.1 (7 rows) SEVEN TIMES — group by `{2}` and take MAX FIRST. The payment fields ({3}, {4}) do differ per row, so a direct SUM is correct for them. ",
  "⚠️ СУУТГАЛ ЭНД БАЙХГҮЙ. `{0}` нь аль хэдийн БОДИТ ОЛГОСОН дүн. «Барьцаа», «урьдчилгааны эргэн төлөлт», «захиалагчийн/зохиогчийн хяналтын суутгал», «цэвэр дүн», «төлөгдөөгүй үлдэгдэл» гэсэн ойлголтууд энэ эх сурвалжид ОГТ бүртгэгддэггүй — асуувал «бүртгэгддэггүй» гэж хариул, бодож гаргах гэж бүү оролд. ": "⚠️ THERE ARE NO DEDUCTIONS HERE. `{0}` is already the ACTUAL DISBURSED amount. The concepts «retention», «advance repayment», «client/author supervision deduction», «net amount» and «unpaid balance» are NOT recorded at all in this source — if asked, answer «not recorded» and do not try to derive them. ",
  "⚠️ АКТЫН ТӨЛӨВ БАЙХГҮЙ. «Хянагдаж байна», «батлагдсан», «хугацаа хэтэрсэн», «төлөх ёстой огноо» — бүгд алга. Мөр бүр нь АЛЬ ХЭДИЙН хийгдсэн гүйлгээ. ": "⚠️ THERE IS NO CERTIFICATE STATUS. «Under review», «approved», «overdue», «due date» — none exist. Every row is a transaction that has ALREADY been executed. ",
  "⚠️ Талбарын нэр `{0}` нь ДООД ЗУРААСТАЙ (толинд `on` гэж бичигдсэн ч үйлчилгээнд өөр) — `on` гэж бичвэл хүсэлт УНАНА. ": "⚠️ The field name `{0}` has a TRAILING UNDERSCORE (the dictionary shows `on`, but the service differs) — writing `on` will make the query FAIL. ",
  "⚠️ `{0}` нь ЗӨВХӨН гүйцэтгэлийн мөрд (22/45); урьдчилгаад ҮРГЭЛЖ хоосон. Гэрээ бүрд 1-ээс эхэлж цоорхойгүй дугаарлагдана — цоорхой олдвол тэр нь ӨГӨГДӨЛ ДУТУУ гэсэн дохио. ": "⚠️ `{0}` exists ONLY on performance rows (22/45); it is ALWAYS empty on advances. It is numbered from 1 with no gaps within each contract — a gap is a signal that DATA IS MISSING. ",
  "⚠️ `{0}` 3 талбар нь 45/45 мөрд МЭДЭЭЛЭЛГҮЙ (null эсвэл 0) — «хүлээгдэж буй гүйцэтгэл тэг» гэж БҮҮ унш. ": "⚠️ The 3 `{0}` fields have NO DATA on 45/45 rows (null or 0) — do NOT read this as «pending performance is zero». ",
  "⚠️ Гэрээтэй ({1}) нэгдэхдээ БАГЦААР: `{0}` → `ds:cashflow2`.`{2}`. Гэрээний код («Багц-1») тэнд БАЙХГҮЙ. Мөн ЭНД зөвхөн 22 гэрээ бий, `ds:cashflow2`-т 76 — багцын 2/3 нь энэ хүснэгтэд ОГТ БАЙХГҮЙ, тиймээс «нийт төсөл» гэсэн тоог ЭНДЭЭС гаргаж БОЛОХГҮЙ. ": "⚠️ Join to contracts ({1}) BY PACKAGE: `{0}` → `ds:cashflow2`.`{2}`. The contract code («Багц-1») DOES NOT EXIST there. Also, there are only 22 contracts HERE versus 76 in `ds:cashflow2` — two thirds of the packages are ENTIRELY ABSENT from this table, so a «total projects» figure must NOT be derived from here. ",
  "⚠️ `{0}` 45-ийн 5-д ХООСОН (null ≠ 0). Сарын цуваанд эдгээрийг ОРУУЛАХГҮЙ — сүүлийн сар руу шахвал хуурамч оргил үүснэ; харин багц/нийт дүнд ҮЛДЭНЭ. Тиймээс «сараар нийлбэр» ба «нийт» хоёр ЗӨРНӨ, зөрүүг хариултад дурд. ": "⚠️ `{0}` is EMPTY on 5 of 45 rows (null ≠ 0). Do NOT include them in the monthly series — forcing them into the last month creates a false spike; they DO remain in package/overall totals. Therefore «sum by month» and «total» WILL DIFFER — mention the discrepancy in the answer. ",
  "⚠️ Огноо БҮГД `DateOnly` — «2026-06-08» гэсэн МӨР, epoch мс БИШ. Сарыг эхний 7 тэмдэгтээс ав. ": "⚠️ ALL dates are `DateOnly` — a STRING like «2026-06-08», NOT epoch ms. Take the month from the first 7 characters. ",
