  "Зурган дээр дарж тухайн нүдний гүн, урсгалын хурд, чиглэл, {0} алхмын түүхийг үзнэ.": "Click the map to see that cell's depth, flow speed, direction and its history across the {0} steps.",
  "Өнгө {0} м/с-д ханана.": "Colour saturates at {0} m/s.",
  "{0} алхам · {1} га": "{0} steps · {1} ha",
  "Хохирол нь ЗАГВАРЧЛАЛЫН бодит үерийн мөрөөр бодогдов — бүх {0} минутын дээд гүн {1} м-ээс дээш газар. Зурган дээр урсаж буй ус ба улаанаар тэмдэглэсэн хохирол НЭГ эх сурвалжтай.": "Damage was computed from the SIMULATED flood footprint — everywhere the maximum depth over the {0} minutes exceeds {1} m. The water flowing on the map and the damage marked in red come from ONE source.",
  "Загварчлал бэлэн биш байсан тул хохирлыг үерийн ЗУРВАСААР (голын ирмэгээс {0} м) тооцов. Загварчлал дуусмагц дахин ажиллуулбал бодит мөрөөр бодогдоно.": "The simulation was not ready, so damage was computed from the flood BUFFER ({0} m from the river bank). Re-run once the simulation finishes to use the real footprint.",
  "Өнгө {0} м-д ханана — түүнээс гүн ус ижил өнгөтэй. Загварын дээд гүн {1} м. Зурагт {2} см-ээс нимгэн ус ч (энгэрийн урсгал) бүдэг харагдана, харин «усанд автсан» талбайд {3} см-ээс тооцно.": "Colour saturates at {0} m — deeper water shares that shade. The model peaks at {1} m. Water as thin as {2} cm (hillslope sheet flow) is drawn faintly, but only {3} cm and deeper counts as flooded area.",
  "Зурсан талбай хэт жижиг эсвэл өндрийн торноос гадуур ({0} нүд)": "The drawn area is too small or falls outside the elevation grid ({0} cells)",
  "Газрын зураг дээр талбай зурна. Загварчлал зөвхөн тэр талбайд бодогдоно.": "Draw an area on the map. The simulation then runs only inside it.",
