  "ХОНХОР: энэ цэг эргэн тойрноосоо {0} м нам тул ус цуглана.": "DEPRESSION: this spot sits {0} m below its surroundings, so water collects here.",
  "ХАВТГАЙ ГАЗАР (налуу {0}%): ус урсаж гарч чадахгүй, тэнд тогтоно.": "FLAT GROUND (slope {0}%): water cannot drain away and ponds here.",
