  "Налуу": "Slope",
  "Хур тунадас нь 3D mesh-ийн талбайд ({0} га) ордог; ус тэндээс өндрийн дагуу урсаж, домэйны ({1} га) захаар гарна. Өндөр: mesh байгаа газар mesh ({2} м нүд, барилга ус хаана), байхгүй газар SRTM DEM (~30 м).": "Rainfall falls on the 3D mesh area ({0} ha); water runs downhill from there and leaves through the edge of the domain ({1} ha). Elevation: the mesh where it exists ({2} m cells — buildings block the water), SRTM DEM elsewhere (~30 m).",
  "Ус ХААШАА урсахыг харуулах байнгын шугам (хураах талбай ≥ 0.5 га). Ус нимгэн (2–4 см) үед ч уулаас хот руу чиглэх зам харагдана.": "A permanent line showing WHERE water runs (catchment ≥ 0.5 ha). Even when the water is thin (2–4 cm), the route from the mountain into the city stays visible.",
