  "Батлах хүснэгт БАЙНА, гэвч түүнийг үүсгэсэн хэрэглэгч танигдахгүй байна. AGOL дээр item-ийн эзнийг super админ руу шилжүүлнэ үү.": "The approval table EXISTS, but the account that created it is not recognised. Reassign the item to a super admin in AGOL.",
