  "Батлах хүснэгт олдсонгүй — админ (super) нэг удаа нэвтрэхэд автоматаар үүснэ.": "Approval table not found — it is created automatically the first time a super admin signs in.",
  "Батлах урсгал уншигдсангүй — сүлжээгээ шалгана уу.": "Could not read the approval flow — check your network.",
  "Түүнийг хүртэл хуваарь илгээх боломжгүй.": "Until then the schedule cannot be submitted.",
  "Эх мөрийг уншиж чадсангүй — засварыг хадгалсангүй.": "The original row could not be read — the edit was not saved.",
  "ҮЕРИЙН тархалт нь ЗАГВАРЧИЛСАН — төслийн 3D mesh-ийн бодит өндөр дээр хөтөч дотор бодогдоно; хэмжсэн үер БИШ. Харуулын байршил, өртсөн объект БОДИТ. Харуулын ЗААЛТ ба АГААРЫН бохирдлын хувилбар нь жишээ өгөгдөл — амьд хэмжилт биш.": "The FLOOD extent is MODELLED — computed in the browser on real elevations from the project's own 3D mesh; it is NOT a measured flood. Station locations and affected objects are REAL. Station READINGS and the AIR pollution scenario are example data — not live measurements.",
  "Лавлагааны урсац": "Reference discharge",
  "Зураг дээрх үерийг {0} м³/с оргил урсацаар бодов ({1} мм/ц хур, рационал арга). Дээрх «лавлагааны урсац» нь харуулын сэрэмжлүүлэх босго — загварын оролт БИШ.": "The flood shown was computed with a peak inflow of {0} m³/s ({1} mm/h rainfall, rational method). The 'reference discharge' above is a station warning threshold — NOT the model input.",
  "Дээрх «лавлагааны урсац» нь харуулын сэрэмжлүүлэх босго — үерийн загварын оролт БИШ. Загвар нь хур тунадаснаас оргил урсацаа өөрөө бодно.": "The 'reference discharge' above is a station warning threshold — NOT the flood model input. The model derives its own peak inflow from rainfall.",
