  "Эх сурвалж: Cashflow_0909. §1 ба §7.1-ийн «нийт төсөв» нь эх Excel-ийн НИЙТ томьёоны хамрах хүрээ (Орон сууцны хороолол + ГИШС), харин энэ хүснэгт нь гэрээний БҮХ мөрийг төрлөөр задалсан тул нийлбэр нь илүү гарна. Зөрүү нь газар чөлөөлөлт, буулгалт цэвэрлэгээ болон хамрах хүрээнээс гадуурх ажлууд.": "Source: Cashflow_0909. The \"total budget\" in §1 and §7.1 follows the scope of the source Excel TOTAL formula (Residential district + GISS), whereas this table breaks down ALL contract rows by type, so its sum is larger. The difference is land acquisition, demolition and clean-up plus works outside that scope.",
