  "Нэмэлт ажил буцаагдсан ({0} мөр, {1}): {2} — мөрүүд хуудсанд буцаж орлоо, засаад дахин батлуулна уу.": "Added work was returned ({0} rows, {1}): {2} — the rows are back on the sheet; edit and resubmit for approval.",
