  "Мөр нэмэгч «Гүйцэтгэл бөглөх» хуудсанд шинэ ажлын мөр нэмж батлуулахаар илгээнэ; батлагч зөвшөөрсний дараа л мөр үндсэн өгөгдөлд үүснэ.": "The row adder adds new work rows on the “Fill progress” page and submits them for approval; the row is created in the master data only after the approver accepts.",
  "⚠️ Гүйцэтгэлийн урсгалаас ТУСДАА: тэр нь тоог, энэ нь ажил гэрээнд байх эсэхийг шийднэ. Мөр нэмэгчийн үүрэг нь «Мөр нэмэх» эрхийг дагуулна.": "⚠️ SEPARATE from the progress flow: that decides quantities, this decides whether the work is in the contract. The row-adder role carries the “Add row” capability.",
  "«{0}»-г нэмэлт ажлын хуваарилалтаас бүрэн хасах уу? «Мөр нэмэх» ба «Нэмэлт ажил батлах» эрх нь мөн буцаагдана.": "Remove “{0}” from the additional-work assignment entirely? The “Add row” and “Approve additional work” capabilities will also be revoked.",
  "⚠️ Батлагч нь мөр нэмэгчтэй ижил хүн — өөрийн нэмсэн ажлыг өөрөө батлах боломжгүй тул энэ багцын нэмэлт ажил гацна. Өөр батлагч нэмнэ үү.": "⚠️ The approver is the same person as the row adder — one cannot approve one's own added work, so additional work for this package will stall. Add another approver.",
  "⚠️ Батлагч томилоогүй — нэмсэн ажлыг хэн ч батлахгүй.": "⚠️ No approver assigned — nobody will approve added work.",
