  "Бичсэний дараа хуудсанд өөр жааз орлоо (зэрэгцээ батлалт) — төлөв «батлагдсан» хэвээр, дахин оролдоно уу.": "Another frame entered the sheet after writing (a concurrent approval) — status stays “approved”, please try again.",
  "Хуудас шинэчлэгдлээ — {0} мөрийн хадгалаагүй ноорог шинэ мөрөнд олдсонгүй тул хаягдав.": "Sheet refreshed — the unsaved draft for {0} rows had no match in the new rows and was dropped.",
  "Хуудас шинэчлэгдлээ — хадгалаагүй ноорог шинэ мөрүүд рүү зөөгдөв.": "Sheet refreshed — the unsaved draft was moved to the new rows.",
  "Нэмэлт ажил батлагдлаа — хадгалаагүй өөрчлөлтөө хадгалаад/илгээгээд хуудсыг шинэчилнэ үү.": "Added work was approved — save or submit your unsaved changes, then refresh the sheet.",
  "Хуудсыг серверээс татна; хадгалаагүй ноорог шинэ мөрүүд рүү (№ · нэрээр) зөөгдөнө": "Reloads the sheet from the server; the unsaved draft is moved to the new rows (by № · name)",
  "Энэ browser-т өмнөх сешнээс үлдсэн, ArcGIS-т хадгалагдаагүй эрхийн өөрчлөлт байна: {0}. Эдгээрийг ТАНЫ эрхээр ArcGIS руу бичих үү? (Хаалтанд — бичсэн хүн; энэ browser-ийн хадгалалтаас уншсан тул баталгаагүй.) «Цуцлах» дарвал зөвхөн энэ сешний өөрчлөлтийг илгээнэ.": "This browser has unsaved permission changes left from an earlier session that never reached ArcGIS: {0}. Write them to ArcGIS with YOUR rights? (In parentheses: who wrote them. This is read from this browser's storage and is not verified.) Press “Cancel” to send only this session's changes.",
  "Ачаалснаас хойш хуудасны мөрүүд засагдлаа (хуваарь зэрэг хадгалагдсан) — юу ч бичсэнгүй, дахин оролдоно уу.": "Sheet rows were edited after loading (a schedule was saved concurrently) — nothing was written, please try again.",
