  "Сонгосон объектуудын утга уншигдаагүй байна. Сонголтоо шинэчлээд дахин оролдоно уу.": "The selected objects' values have not been loaded. Refresh your selection and try again.",
  "Гэрээний бүртгэлд нийтлээгүй засвар байна. Таб солибол алдагдана. Үргэлжлүүлэх үү?": "The contract register has unpublished edits. Switching tabs will discard them. Continue?",
  "Өмнөх агшныг уншиж чадсангүй — аль нүд өөрчлөгдсөнийг тодорхойлж чадаагүй тул батлах товч түр хаалттай.": "Could not read the previous snapshot — the changed cells could not be determined, so the approve button is temporarily disabled.",
  "Илгээлтийн агуулга татагдаагүй тул шийдвэр гаргах боломжгүй": "The submission content has not loaded, so no decision can be made",
  "Гүйцэтгэлийн обьём · үнэ · зөрүүгийн багана өгөгдөл орсон үед автоматаар нэмэгдэнэ. Одоогийн төлбөрүүд бөглөлтийн архив эхлэхээс өмнөх тул холбогдох гүйцэтгэл алга.": "Performed volume · price · variance columns are added automatically once data is available. Current payments predate the start of the fill archive, so there is no linked performance.",
