  "хасах": "remove",
  "Хэрэглэгчийн карт — бүх эрх, хуваарилалт нэг дор": "User card — all rights and allocations in one place",
  "«{0}»-ийн энэ үүргийг БҮХ багцаас хасах уу? Өөр үүрэг түүн рүү заагаагүй бол харгалзах эрх нь мөн буцаагдана.": "Remove this role of «{0}» from ALL packages? The matching right is also revoked unless another role maps to it.",
  "«{0}»-г {1} шатнаас {2} шат руу шилжүүлэх үү? Нэг аккаунт зөвхөн нэг шатанд байна — хуучин багцууд ба «Зөвхөн харна» тохиргоо арилж, шинэ шатанд «{3}» хүрээгээр томилогдоно.": "Move «{0}» from stage {1} to {2}? An account can be in only one stage — the old packages and the «View only» setting are cleared, and the new stage is assigned with scope «{3}».",
  "Эхлээд хадгална уу — хуваарилалт хадгалагдсан аккаунтад л олгогдоно.": "Save first — allocations can only be given to saved accounts.",
  "Устгахаар тэмдэглэсэн — хуваарилалт засахгүй.": "Marked for deletion — allocations cannot be edited.",
  "Хадгалаагүй ноорогтой — урсгалын томилгоо энэ хүний эрхийн мөрийг бичдэг тул эхлээд «Хадгалах» эсвэл «Болих» дарна уу.": "Unsaved draft — the flow assignment writes this person's permission row, so press «Save» or «Cancel» first.",
  "Дарж засна": "Click to edit",
  "Улаан нүд — ажил гацна (дээрх «Анхаарах»). Саарал нэр — зөвхөн харна, шатны эзэн биш.": "Red cell — work will stall (see «Attention» above). Grey name — view only, not a stage owner.",
  "Админ {0} — бүх багцад (хуваарилалт үйлчлэхгүй).": "Admins {0} — in all packages (allocation does not apply).",
  "Засвар бүгд нэг бичих давхаргаар — матриц, хэрэглэгчийн карт, бүлгийн хуудас ижил дүрмээр бичиж, ижил асуулт асууна. Хуваарилалт шууд хадгалагдана.": "All edits go through one write layer — the matrix, user card and group pages write with the same rules and ask the same questions. Allocations are saved immediately.",
  "Төслийн нийт гүйцэтгэл": "Overall project progress",
  "Нэгтгэл гүйцэтгэлээр": "From the consolidated progress table",
  "Нэгтгэл гүйцэтгэлийн хүснэгтээс (Negtgel_guitsetgel)": "From the consolidated progress table (Negtgel_guitsetgel)",
  "Энэ хэсэгт төслийн цар хүрээ, гүйцэтгэл, санхүүжилтийн долоон гол үзүүлэлтийг нэгтгэв. Гүйцэтгэлийн хоёр өөр хэмжүүрийг ялган үзэх нь зүйтэй: орон сууцны багцуудын жигнэсэн гүйцэтгэл нь багц бүрийн блокийн дундажийг төсвийн жингээр нь нэгтгэсэн дүн бол барилга угсралтын гүйцэтгэл нь бүх блокийн энгийн дундаж. Удирдлагын тайлангийн «Төслийн нийт гүйцэтгэл» нь өөр хэмжүүр буюу нэгтгэл гүйцэтгэлийн хүснэгтэд ТЭЗҮ-гээс төсөл хүлээлгэн өгөх хүртэлх үе шатыг төсөлд эзлэх хувиар нь нэгтгэсэн дүн.": "This section brings together seven key indicators of project scope, progress and financing. Two different progress measures should be distinguished: the weighted housing-package progress aggregates each package's block average by its budget weight, while construction progress is the simple average of all blocks. The executive report's «Overall project progress» is yet another measure — the consolidated progress table's stages, from the feasibility study to project handover, combined by their share of the project.",
  "Нэгтгэл гүйцэтгэлийн хүснэгтэд ТЭЗҮ-гээс төсөл хүлээлгэн өгөх хүртэлх үе шатыг төсөлд эзлэх хувиар нь нэгтгэсэн дүн.": "The consolidated progress table's stages, from the feasibility study to project handover, combined by their share of the project.",
