  "Багцын ТӨЛӨВЛӨГӨӨНИЙ хуваарь бүтэн дэлгэцээр нээгдэнэ — өөрчлөгдсөн мөр бүрийг зөвшөөрч батална.": "Opens the package PLANNED schedule full screen — approve each changed row, then approve.",
  "Хуваарийг харж батлах": "Review and approve schedule",
  "«{0}» талбар богино ({1} тэмдэгт) — зөвшөөрсөн мөрийн тэмдэглэгээ багтсангүй (шийдвэр хадгалагдсан). AGOL дээр талбарын уртыг 65536 болгоно уу.": "The «{0}» field is too short ({1} characters) — row approvals did not fit (the decision was saved). Set the field length to 65536 in AGOL.",
  "Батлах хүснэгтэд «{0}» талбар алга — зөвшөөрсөн мөрийн тэмдэглэгээ хадгалагдсангүй (шийдвэр хадгалагдсан). AGOL дээр String (урт 65536) талбар нэмнэ үү.": "The approval table has no «{0}» field — row approvals were not saved (the decision was saved). Add a String field (length 65536) in AGOL.",
