  "Чанарын баримт (MS · QMP · PRC · MA · MIR · FIC · NCR)": "Quality documents (MS · QMP · PRC · MA · MIR · FIC · NCR)",
  "Ажлын аргачлал (MS) · чанарын удирдлагын төлөвлөгөө (QMP) · процедур (PRC) · материал баталгаажуулалт (MA) · материалын/талбайн үзлэг (MIR · FIC) · үл тохирол (NCR) — ирүүлсэн хувилбар, хянагчдын A/AN/R шийдвэр, REP дугаар, хавсралт.": "Method statements (MS) · quality management plans (QMP) · procedures (PRC) · material approvals (MA) · material/field inspections (MIR · FIC) · non-conformances (NCR) — submitted revisions, reviewers’ A/AN/R verdicts, REP numbers, attachments.",
  "Хянагчид төрлөөр (chanarReview): MS · QMP · PRC — ТУХ · Чанар · ХАБЭА зэрэг; MA — ЧХ инженер → Чанар → ТУГ дараалсан; MIR · FIC — ТУХ → Чанар дараалсан; NCR — залруулгын дараа ТУХ · Чанар · ТУГ зэрэг": "Reviewers by kind (chanarReview): MS · QMP · PRC — PMC · Quality · HSE in parallel; MA — QC engineer → Quality → PMO sequential; MIR · FIC — PMC → Quality sequential; NCR — after correction PMC · Quality · PMO in parallel",
  "Бүгд A/AN бол «Батлагдсан» · нэг R бол гүйцэтгэгчид буцна (rev+1; NCR-д rev үгүй) · хариу бүрд SLB-REP-<төрөл>-P<багц>-<NNNN>-<RR> дугаар (RR = хариуны тоо); NCR-ийн дугаар STMCC-STMC-NCR-NNNN": "All A/AN → “Approved” · one R → returned to contractor (rev+1; NCR has no rev) · each reply gets an SLB-REP-<kind>-P<pkg>-<NNNN>-<RR> number (RR = reply count); NCR number STMCC-STMC-NCR-NNNN",
  "Хүснэгтийг super админы токеноор код өөрөө үүсгэнэ (createService). Схем 7 төрөлд нийтлэг — төрлийн нэмэлт өгөгдөл body/reviews JSON дотор.": "The table is created by the code itself with the super admin token (createService). One schema for all 7 kinds — kind-specific data lives inside the body/reviews JSON.",
