  "Төсвөөр жигнэсэн": "Budget-weighted",
  "Бүлэг бүрийн оноо багц ажлын урьдчилсан төсөвт өртгөөр жигнэсэн. Нийт оноо = оноотой бүлгүүдийн дундаж.": "Each dimension is weighted by the works' estimated budget cost. Total = mean of the scored dimensions.",
  "Бүлгийн мөр: төсвөөр жигнэсэн бүлгийн дундажуудын дундаж. Ажлын мөр: бүлгүүдийн дундаж.": "Group row: mean of budget-weighted dimension averages. Work row: mean of its dimensions.",
  "Гүйцэтгэлийг баталж архивт бүртгэх үү? Архив болон нэгтгэлд бичигдэж, үндсэн өгөгдөлд орно.": "Approve this progress and record it in the archive? It will be written to the archive and consolidation and enter the main data.",
