  "Энэ ажлыг {0} таныг шийдвэрлэж байх хооронд аль хэдийн шийдвэрлэсэн — таны шийдвэр хадгалагдсангүй, жагсаалт шинэчлэгдлээ.": "{0} already decided on this item while you were reviewing — your decision was not saved; the list has been refreshed.",
