  "Хянагч шийдвэр өгч эхэлсэн тул хянахгүй буцаах боломжгүй — «Татгалзсан (R)» шийдвэр өгнө үү": "A reviewer has already decided — it can no longer be returned unreviewed; give a “Rejected (R)” decision instead",
  "Дахин нээх шалтгаанаа бичнэ үү.": "Enter the reason for reopening.",
  "Баримт өөр хэрэглэгчээр зэрэг өөрчлөгдөж байна — «Шинэчлэх» дараад дахин оролдоно уу.": "Another user is changing this document at the same time — press “Refresh” and try again.",
  "⚠️ Нэг хүн хоёр үүрэгт — баримт гацна ({0}): {1} нь {2} үүргийн цорын ганц хянагч. Нэг хүн зөвхөн нэг үүргээр хянадаг тул үүрэг тус бүрд өөр хүн томилно уу.": "⚠️ One person in two roles — documents will get stuck ({0}): {1} is the only reviewer for {2}. A person may review in only one role, so assign a different person to each role.",
  "Үл тохирол «Нэмэлт арга хэмжээ шаардлагатай» болж, гүйцэтгэгч залруулгаа дахин илгээнэ.": "The NCR becomes “Further action required” and the contractor resubmits the correction.",
  "Баримт гүйцэтгэгч рүү буцаагдаж, захиалагчийн хариу (REP) дугаар олгогдоно — гүйцэтгэгч засаад шинэ хувилбар илгээнэ.": "The document is returned to the contractor and a client response (REP) number is issued — the contractor revises and submits a new revision.",
  "Та сүүлийн дүгнэгч — үл тохирол хаагдаж, захиалагчийн хариу (REP) дугаар олгогдоно.": "You are the last reviewer — the NCR will be closed and a client response (REP) number issued.",
