  "{0} төлөвлөгөөнөөс": "{0} vs plan",
  "3D зураглалын чанар": "3D rendering quality",
  "Хурдан": "Fast",
  "Нарийн": "Detailed",
  "Хурдан — гөлгөр хөдөлгөөн: BIM-ийн гадна бүрхүүл, ойрын барилга бүрэн, сүүдэр/тусгалгүй": "Fast — smooth navigation: BIM exterior shell, nearest buildings in full, no shadows/reflections",
  "Нарийн — BIM-ийн бүх элемент, өндөр чанар (удаан ачаална)": "Detailed — every BIM element, high quality (loads slowly)",
  "Ерөнхий дашбоард · Багцын гүйцэтгэл · Багцын санхүү · Зөвшөөрөл": "General dashboard · Package progress · Package finance · Permits",
  "Төслийн удирдлагын хэсэг, багцын менежер": "Project management unit, package managers",
  "Багцын хамаарлын бичлэг эвдэрсэн байна": "The package dependency record is corrupted",
  "Багцыг өөртэй нь холбох боломжгүй": "A package cannot depend on itself",
