  "Хадгалаагүй ажил байна — дахин нэвтрэхэд алдагдана. Эхлээд «Түр хаах» дарж ажлаа хуулж авна уу. Үргэлжлүүлэх бол «Дахин нэвтрэх»-ийг дахин дарна уу.": "You have unsaved work — signing in again will discard it. First press “Close for now” and copy your work. To continue, press “Sign in again” once more.",
