  "Энэ багцын хуваарийн илгээлтийг батлагч ({0}) эх хуудсанд ХЭСЭГЧЛЭН бичсэн байна — тэр батлалт гүйцэгдэх (эсвэл буцаагдах) хүртэл нэмэлт ажлыг буулгах боломжгүй: жааз солигдвол хагас бичилт алдагдана.": "The approver ({0}) has PARTIALLY written this package's schedule submission to the sheet — additional work cannot be applied until that approval is completed (or returned): a frame change would lose the partial write.",
