  "Хөрсний цахилгаан дамжуулах чадал (EC) — давсжилт, бордооны агууламжийн шууд бус хэмжүүр. USDA-гийн ангиллаар давсжаагүй хөрс нь 2,000 µS/cm-ээс доош; хэмжигдсэн дээд нь 135.": "Soil electrical conductivity (EC) — an indirect measure of salinity and fertiliser content. Under the USDA classification, non-saline soil is below 2,000 µS/cm; the highest measured value is 135.",
