  "{0} нүдийг ачаалснаас хойш өөр хэрэглэгч өөрчилсөн тул бичсэнгүй — таны засвар хадгалаагүй хэвээр үлдэв: {1}. Шинэ утгыг шалгаад дахин «Хадгалах» дарвал таны утгаар солигдоно.": "{0} cell(s) were changed by another user since loading, so they were not written — your edits remain unsaved: {1}. Review the new values; pressing «Save» again will replace them with yours.",
