  "{0}: сүүлийн агшин дутуу — {1} мөр ирлээ, дор хаяж {2} байх ёстой. Нийтлэл дундаа тасарсан байж болзошгүй — дахин нийтлэх эсвэл админд хандана уу.": "{0}: the latest snapshot is incomplete — {1} rows received, at least {2} expected. A publish may have been interrupted — republish or contact an admin.",
  "Энэ илгээлтийг та өөр цонхноос аль хэдийн баталсан байна — үндсэн өгөгдөлд бичигдсэн.": "You already approved this submission in another window — it has been written to the main data.",
  "{0} нүд архивын сүүлийн жаазад тулгагдсангүй — тэдгээр нь үндсэн өгөгдөлд БИЧИГДЭХГҮЙ: {1}. Үлдсэн {2} нүдийг батлах уу? Алгассан нүд илгээлтийн тайлбарт тэмдэглэгдэнэ.": "{0} cells could not be matched to the latest archive frame — they will NOT be written to the main data: {1}. Approve the remaining {2} cells? The skipped cells will be recorded in the submission note.",
  "Батлалт цуцлагдлаа — {0} нүд сүүлийн жаазад тулгагдсангүй: {1}. Буцааж, инженерээр дахин илгээлгэнэ үү.": "Approval cancelled — {0} cells could not be matched to the latest frame: {1}. Return it and have the engineer resubmit.",
  "Бичих зуур хуудасны жааз солигдсон (өөр батлалт/нийтлэл) — утга хуучин жаазад бичигдсэн байж болзошгүй. Илгээлт «Хүлээгдэж буй» хэвээр; хуудсаа шинэчлээд «Обьём батлах»-ыг дахин дарна уу.": "The sheet frame changed during the write (another approval/publish) — values may have been written to the old frame. The submission is still «Pending»; refresh the page and press «Approve volume» again.",
  "Бичсэний дараах жаазын шалгалт унав — илгээлт «Хүлээгдэж буй» хэвээр; хуудсаа шинэчлээд «Обьём батлах»-ыг дахин дарна уу.": "The post-write frame check failed — the submission is still «Pending»; refresh the page and press «Approve volume» again.",
